// weapon.js —— 玩家武器系统
// 职责：管理当前武器、射击（射线检测命中敌人/墙）、换弹、武器切换、
//        后坐力、弹道散布、第一人称枪模、弹孔/枪口火光等视觉反馈
// 射击命中判定：从相机发出带散布的射线，与敌人胶囊体（球+圆柱近似）求最近交点，
//                并与地图 AABB 比较——若墙更近则被墙挡住。
// 经典脚本（非 ES Module）：THREE / CONFIG 由前置脚本挂到 window 提供

class WeaponSystem {
  constructor(scene, camera, player, gameMap, enemies, hud, audio) {
    this.scene = scene;
    this.camera = camera;
    this.player = player;
    this.map = gameMap;
    this.enemies = enemies;     // 引用数组（动态）
    this.hud = hud;
    this.audio = audio;

    // 当前武器
    this.currentId = 'usp';
    this.state = this._freshState('usp');

    // 输入
    this.firing = false;        // 鼠标按下持续射击
    this.fireCooldown = 0;
    this.reloadTimer = 0;
    this.switching = false;
    this._bindInput();

    // 第一人称枪模
    this._buildViewModel();
    // 弹道轨迹池（临时线段）
    this._tracers = [];
    this._impacts = [];         // 弹孔
    this._buildImpactPool();
    // 枪口火光
    this._muzzleFlash = null;
    this._muzzleTimer = 0;
  }

  _freshState(id) {
    const w = CONFIG.weapons[id];
    return {
      id,
      mag: w.magSize,
      reserve: w.reserve,
    };
  }

  _bindInput() {
    this._onMouseDown = (e) => {
      if (e.button === 0) this.firing = true;
    };
    this._onMouseUp = (e) => {
      if (e.button === 0) this.firing = false;
    };
    this._onKeyDown = (e) => {
      if (e.code === 'KeyR') this.startReload();
      if (e.code === 'Digit1') this.switchTo('usp');
      if (e.code === 'Digit2') this.switchTo('ak47');
    };
    // 触屏设备：原生 mouse 事件会由"点击屏幕视角区"合成触发导致误开火，
    // 因此只保留键盘；射击统一走 FIRE 按钮的 setFiring()
    const isTouch = ('ontouchstart' in window) || navigator.maxTouchPoints > 0;
    if (!isTouch) {
      window.addEventListener('mousedown', this._onMouseDown);
      window.addEventListener('mouseup', this._onMouseUp);
    }
    window.addEventListener('keydown', this._onKeyDown);
  }

  // 触屏 FIRE 按钮 / 外部直接控制持续射击状态（自动武器）
  setFiring(v) {
    this.firing = v;
  }

  switchTo(id) {
    if (id === this.currentId) return;
    if (!CONFIG.weapons[id]) return;
    // 保留每种武器的弹匣状态
    if (!this._stash) this._stash = {};
    this._stash[this.currentId] = { ...this.state };
    this.currentId = id;
    this.state = this._stash[id] ? { ...this._stash[id] } : this._freshState(id);
    this.reloadTimer = 0;
    this.fireCooldown = 0.3;    // 切枪延迟
    this.firing = false;
    this.hud.updateWeapon(CONFIG.weapons[id], this.state);
    this.hud.toast(CONFIG.weapons[id].name);
  }

  startReload() {
    const w = CONFIG.weapons[this.currentId];
    if (this.reloadTimer > 0) return;
    if (this.state.mag >= w.magSize) return;
    if (this.state.reserve <= 0) return;
    this.reloadTimer = w.reloadTime;
    this.hud.toast('换弹中…');
  }

  _finishReload() {
    const w = CONFIG.weapons[this.currentId];
    const need = w.magSize - this.state.mag;
    const take = Math.min(need, this.state.reserve);
    this.state.mag += take;
    this.state.reserve -= take;
    this.hud.updateWeapon(w, this.state);
  }

  // ---------- 主更新 ----------
  update(dt) {
    const w = CONFIG.weapons[this.currentId];

    // 换弹
    if (this.reloadTimer > 0) {
      this.reloadTimer -= dt;
      if (this.reloadTimer <= 0) this._finishReload();
    }

    // 射击冷却
    if (this.fireCooldown > 0) this.fireCooldown -= dt;

    // 持续射击（自动武器）
    const wantFire = this.firing && w.type === 'auto';
    const wantFireSemi = this._semiPending;
    if ((wantFire || wantFireSemi) && this.fireCooldown <= 0 && this.reloadTimer <= 0) {
      this._fire();
      this._semiPending = false;
    }

    // 准星扩散与当前散布联动（静止收拢、移动张开，所见即所射）
    const hSpeed = Math.hypot(this.player.velocity.x, this.player.velocity.z);
    const moveFactor = Math.min(1, hSpeed / CONFIG.player.walkSpeed);
    const curSpread = w.spread + w.spreadMove * moveFactor;
    this.hud.setCrosshairSpread(curSpread);

    // 枪模动画
    this._updateViewModel(dt);

    // 弹道/弹孔淡出
    this._updateTracers(dt);

    // 枪口火光衰减
    if (this._muzzleTimer > 0) {
      this._muzzleTimer -= dt;
      if (this._muzzleFlash) this._muzzleFlash.material.opacity = Math.max(0, this._muzzleTimer / 0.04);
    }
  }

  // 半自动：鼠标按下触发一次
  triggerSemi() {
    const w = CONFIG.weapons[this.currentId];
    if (w.type === 'semi') this._semiPending = true;
  }

  _fire() {
    const w = CONFIG.weapons[this.currentId];
    if (this.state.mag <= 0) {
      // 空仓
      this.hud.toast('弹匣空了！按 R 换弹');
      this.fireCooldown = 0.2;
      this.firing = false;
      if (w.autoReload) this.startReload();
      return;
    }
    this.state.mag--;
    this.fireCooldown = w.fireRate;
    this.hud.updateWeapon(w, this.state);
    this.hud.crosshairFire();

    // 计算弹道方向（带散布）
    const ray = this.player.getAimRay();
    // 移动时散布更大
    const hSpeed = Math.hypot(this.player.velocity.x, this.player.velocity.z);
    const moveFactor = Math.min(1, hSpeed / CONFIG.player.walkSpeed);
    const spread = w.spread + w.spreadMove * moveFactor;
    const dir = ray.direction.clone();
    // 在"屏幕平面"内做圆盘均匀采样（用相机右/上向量做基），
    // 保证弹孔分布始终落在准星扩散范围内，且朝向任意角度都不会畸变
    if (spread > 0) {
      const right = new THREE.Vector3(1, 0, 0).applyQuaternion(this.camera.quaternion);
      const up = new THREE.Vector3(0, 1, 0).applyQuaternion(this.camera.quaternion);
      const ang = Math.random() * Math.PI * 2;
      const rad = spread * Math.sqrt(Math.random());
      dir.addScaledVector(right, Math.cos(ang) * rad)
         .addScaledVector(up, Math.sin(ang) * rad)
         .normalize();
    }

    const origin = ray.origin.clone();

    // 后坐力
    this.player.applyRecoil(w.recoil);

    // 命中判定：找最近的敌人；同时与地图求交判断是否被墙挡住
    let bestEnemy = null;
    let bestT = Infinity;
    let bestPart = 'body';
    for (const en of this.enemies) {
      if (!en.alive) continue;
      const hit = intersectCapsule(origin, dir, en);
      if (hit && hit.t < bestT) { bestT = hit.t; bestEnemy = en; bestPart = hit.part; }
    }
    // 墙距离
    const wallT = this.map.raycast(origin, dir, w.range);

    // 视觉：弹道轨迹终点
    let endT = w.range;
    if (wallT < endT) endT = wallT;
    if (bestEnemy && bestT < endT) endT = bestT;

    const endPoint = origin.clone().add(dir.clone().multiplyScalar(endT));
    this._spawnTracer(origin, endPoint);
    this._spawnMuzzleFlash();

    // 命中处理
    if (bestEnemy && bestT < wallT) {
      let dmg = w.damage;
      if (bestPart === 'head') dmg *= w.headMult;
      else if (bestPart === 'leg') dmg *= w.legMult;
      const killed = bestEnemy.takeDamage(dmg, bestPart);
      this.hud.hitMarker(bestPart === 'head');
      if (killed) {
        this.hud.killFeed(bestEnemy.name);
      }
    } else if (wallT < w.range) {
      // 击中墙体，留弹孔
      this._spawnImpact(endPoint, dir);
    }

    // 音效
    if (this.audio) this.audio.shot(this.currentId);
  }

  // ---------- 视觉：第一人称枪模 ----------
  _buildViewModel() {
    this._viewGroup = new THREE.Group();
    this.camera.add(this._viewGroup);
    this.scene.add(this.camera);   // 确保 camera 加入场景，枪模跟随

    // 简易枪身（盒子组合）
    const gunMat = new THREE.MeshStandardMaterial({ color: 0x222226, roughness: 0.6, metalness: 0.4 });
    const body = new THREE.Mesh(new THREE.BoxGeometry(0.08, 0.12, 0.5), gunMat);
    body.position.set(0.22, -0.2, -0.5);
    this._viewGroup.add(body);

    const barrel = new THREE.Mesh(new THREE.BoxGeometry(0.04, 0.04, 0.3), gunMat);
    barrel.position.set(0.22, -0.16, -0.75);
    this._viewGroup.add(barrel);

    const grip = new THREE.Mesh(new THREE.BoxGeometry(0.06, 0.18, 0.08), gunMat);
    grip.position.set(0.22, -0.3, -0.35);
    this._viewGroup.add(grip);

    // AK 时显示更长枪管 + 弹匣
    const mag = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.16, 0.1),
      new THREE.MeshStandardMaterial({ color: 0x6a4a2a, roughness: 0.8 }));
    mag.position.set(0.22, -0.32, -0.4);
    mag.rotation.x = 0.25;
    mag.visible = false;
    this._viewGroup.add(mag);
    this._viewMag = mag;

    // 枪口火光（始终在枪口位置）
    const flashMat = new THREE.MeshBasicMaterial({
      color: 0xffcc44, transparent: true, opacity: 0, depthTest: false,
    });
    const flash = new THREE.Mesh(new THREE.SphereGeometry(0.06, 8, 8), flashMat);
    flash.position.set(0.22, -0.16, -0.92);
    this._viewGroup.add(flash);
    this._muzzleFlash = flash;

    // 当前枪模姿态
    this._viewRecoil = 0;
  }

  _spawnMuzzleFlash() {
    if (this._muzzleFlash) {
      this._muzzleFlash.material.opacity = 1;
      this._muzzleFlash.scale.setScalar(0.8 + Math.random() * 0.6);
      this._muzzleFlash.rotation.z = Math.random() * Math.PI;
      this._muzzleTimer = 0.04;
    }
    // 枪模后坐位移
    this._viewRecoil = 1;
  }

  _updateViewModel(dt) {
    const w = CONFIG.weapons[this.currentId];
    // AK 弹匣显隐
    if (this._viewMag) this._viewMag.visible = (this.currentId === 'ak47');

    // ---- 后坐力回弹：枪口向上挑（rotation.x 正值 = 前方枪口抬起）+ 轻微后缩 ----
    this._viewRecoil = Math.max(0, this._viewRecoil - dt * 8);
    const kick = this._viewRecoil;
    // 上挑角度随武器后坐力参数放大（峰值 ≈ 7°~9°，视觉明显上跳）
    const recoilPitch = kick * (0.09 + w.recoil.x * 3.2);
    const recoilPush = kick * 0.05;      // 轻微后缩

    // 走路晃动
    const bob = Math.sin(this.player.viewBob * 2) * 0.01;
    this._viewGroup.position.x = bob * 0.5;
    this._viewGroup.position.y = -Math.abs(bob) * 0.5;
    this._viewGroup.position.z = recoilPush;

    // 换弹时枪下倾（与后坐上挑叠加，不再互相覆盖）
    let dip = 0;
    if (this.reloadTimer > 0) {
      const t = 1 - this.reloadTimer / w.reloadTime;
      dip = Math.sin(t * Math.PI) * 0.4;
    }
    this._viewGroup.rotation.x = recoilPitch + dip;
  }

  // ---------- 弹道与弹孔 ----------
  _spawnTracer(from, to) {
    // 池化复用：避免每发子弹 new Geometry/Line（高频分配触发 GC 卡顿）
    let line = this._tracerPool && this._tracerPool.pop();
    if (!line) {
      const geo = new THREE.BufferGeometry().setFromPoints([from, to]);
      const mat = new THREE.LineBasicMaterial({
        color: 0xffee88, transparent: true, opacity: 0.8,
      });
      line = new THREE.Line(geo, mat);
      this._tracerPool = this._tracerPool || [];
    } else {
      line.geometry.setFromPoints([from, to]);
    }
    line.userData.life = 0.06;
    line.material.opacity = 0.8;
    line.visible = true;
    this.scene.add(line);
    this._tracers.push(line);
  }

  _updateTracers(dt) {
    for (let i = this._tracers.length - 1; i >= 0; i--) {
      const t = this._tracers[i];
      t.userData.life -= dt;
      t.material.opacity = Math.max(0, t.userData.life / 0.06) * 0.8;
      if (t.userData.life <= 0) {
        this.scene.remove(t);
        t.visible = false;
        this._tracerPool.push(t);   // 归还池中复用，不再 dispose
        this._tracers.splice(i, 1);
      }
    }
    for (let i = this._impacts.length - 1; i >= 0; i--) {
      const m = this._impacts[i];
      m.userData.life -= dt;
      if (m.userData.life <= 0) {
        this.scene.remove(m);
        this._impactPool.push(m);
        this._impacts.splice(i, 1);
      }
    }
  }

  _buildImpactPool() {
    this._impactPool = [];
    const geo = new THREE.CircleGeometry(0.06, 8);
    const mat = new THREE.MeshBasicMaterial({
      color: 0x111111, transparent: true, opacity: 0.9, side: THREE.DoubleSide,
    });
    for (let i = 0; i < 30; i++) {
      const m = new THREE.Mesh(geo, mat.clone());
      m.visible = false;
      this.scene.add(m);
      this._impactPool.push(m);
    }
  }

  _spawnImpact(point, dir) {
    let m = this._impactPool.pop();
    if (!m) return;
    m.position.copy(point).add(dir.clone().multiplyScalar(-0.02));
    m.lookAt(point.clone().add(dir));
    m.visible = true;
    m.material.opacity = 0.9;
    m.userData.life = 6;
    this.scene.add(m);
    this._impacts.push(m);
  }

  reset() {
    this.currentId = 'usp';
    this.state = this._freshState('usp');
    this._stash = {};
    this.firing = false;
    this.reloadTimer = 0;
    this.fireCooldown = 0;
    this.hud.updateWeapon(CONFIG.weapons.usp, this.state);
  }

  dispose() {
    window.removeEventListener('mousedown', this._onMouseDown);
    window.removeEventListener('mouseup', this._onMouseUp);
    window.removeEventListener('keydown', this._onKeyDown);
  }
}

// 射线 vs 胶囊（敌人）：用两段球 + 中间圆柱近似
// 返回 { t, part } 或 null。part ∈ 'head' | 'body' | 'leg'
function intersectCapsule(origin, dir, enemy) {
  // 敌人几何：脚底 y=0，身高 H，头球中心在 y=H-0.15，半径 0.22
  // 身体圆柱 y ∈ [0.3, H-0.3]，半径 0.35；腿部 y ∈ [0, 0.3]
  const H = enemy.height;
  const center = enemy.position;     // 脚底 XZ 中心
  // 头球
  const headCenter = new THREE.Vector3(center.x, H - 0.15, center.z);
  const headHit = raySphere(origin, dir, headCenter, 0.22);
  // 身体圆柱（沿 Y），用 XZ 平面求交 + Y 范围
  const bodyHit = rayVerticalCylinder(origin, dir, center.x, center.z, 0.38, 0.45, H - 0.35);
  // 腿圆柱
  const legHit = rayVerticalCylinder(origin, dir, center.x, center.z, 0.3, 0.0, 0.45);

  let best = null;
  if (headHit !== null && (best === null || headHit < best.t)) best = { t: headHit, part: 'head' };
  if (bodyHit !== null && (best === null || bodyHit < best.t)) best = { t: bodyHit, part: 'body' };
  if (legHit !== null && (best === null || legHit < best.t)) best = { t: legHit, part: 'leg' };
  return best;
}

function raySphere(o, d, c, r) {
  const oc = { x: o.x - c.x, y: o.y - c.y, z: o.z - c.z };
  const a = d.x * d.x + d.y * d.y + d.z * d.z;
  const b = 2 * (oc.x * d.x + oc.y * d.y + oc.z * d.z);
  const cc = oc.x * oc.x + oc.y * oc.y + oc.z * oc.z - r * r;
  const disc = b * b - 4 * a * cc;
  if (disc < 0) return null;
  const t = (-b - Math.sqrt(disc)) / (2 * a);
  return t >= 0 ? t : null;
}

// 射线 vs 垂直圆柱（无限高），再裁剪到 [yMin, yMax]
function rayVerticalCylinder(o, d, cx, cz, r, yMin, yMax) {
  const dx = o.x - cx, dz = o.z - cz;
  const a = d.x * d.x + d.z * d.z;
  if (a < 1e-9) return null;
  const b = 2 * (dx * d.x + dz * d.z);
  const c = dx * dx + dz * dz - r * r;
  const disc = b * b - 4 * a * c;
  if (disc < 0) return null;
  const sq = Math.sqrt(disc);
  let t = (-b - sq) / (2 * a);
  if (t < 0) t = (-b + sq) / (2 * a);
  if (t < 0) return null;
  const y = o.y + d.y * t;
  if (y < yMin || y > yMax) {
    // 检查另一个解
    let t2 = (-b + sq) / (2 * a);
    if (t2 < 0) return null;
    const y2 = o.y + d.y * t2;
    if (y2 < yMin || y2 > yMax) return null;
    return t2;
  }
  return t;
}

// 经典脚本全局暴露（依赖顺序：config → three(UMD) → map → player → enemy → weapon → …）
window.WeaponSystem = WeaponSystem;
